def solve(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    def nonzero_cols(row):
        return [i for i, v in enumerate(row) if v != 0]

    def is_checker_group(rows):
        patterns = []
        for r in rows:
            cols = nonzero_cols(out[r])
            if not cols:
                return False
            if len(cols) >= 2:
                step = cols[1] - cols[0]
                if step != 2:
                    return False
                for i in range(1, len(cols)):
                    if cols[i] - cols[i - 1] != 2:
                        return False
            patterns.append(cols[0] % 2)
        return True

    # Find contiguous non-empty row groups
    groups = []
    r = 0
    while r < h:
        if any(v != 0 for v in out[r]):
            s = r
            while r < h and any(v != 0 for v in out[r]):
                r += 1
            groups.append((s, r - 1))
        else:
            r += 1

    for s, e in groups:
        rows = list(range(s, e + 1))
        cols_by_row = [nonzero_cols(out[r]) for r in rows]

        # Checkerboard-like groups: extend same parity to the right edge
        if is_checker_group(rows):
            for r in rows:
                cols = nonzero_cols(out[r])
                if not cols:
                    continue
                parity = cols[0] % 2
                last = cols[-1]
                for c in range(last + 2, w, 2):
                    if c % 2 == parity:
                        out[r][c] = 1
            continue

        # Contiguous-segment groups
        contiguous = True
        starts = []
        ends = []
        for cols in cols_by_row:
            if not cols:
                contiguous = False
                break
            if cols != list(range(cols[0], cols[-1] + 1)):
                contiguous = False
                break
            starts.append(cols[0])
            ends.append(cols[-1])

        if not contiguous:
            continue

        if len(rows) == 1:
            # Single-row prefix -> extend to the right edge
            r = rows[0]
            for c in range(ends[0] + 1, w):
                out[r][c] = 1
            continue

        # Multi-row contiguous groups:
        # extend rows whose segment does not start at the left edge
        # (these are trailing rows in the observed tasks)
        for idx, r in enumerate(rows):
            if starts[idx] > 0:
                for c in range(ends[idx] + 1, w):
                    out[r][c] = 1

    return out

